'use client'

import { useEffect } from 'react'

declare global {
  interface Window {
    VLibras: {
      Widget: new (url: string) => void
    }
  }
}

export const VLibras = () => {
  useEffect(() => {
    // Adiciona o script do VLibras
    const script = document.createElement('script')
    script.src = 'https://vlibras.gov.br/app/vlibras-plugin.js'
    script.async = true
    
    script.onload = () => {
      // Inicializa o widget do VLibras
      new window.VLibras.Widget('https://vlibras.gov.br/app')
    }

    document.head.appendChild(script)

    return () => {
      if (document.head.contains(script)) {
        document.head.removeChild(script)
      }
    }
  }, [])

  // Usando JSX.IntrinsicElements para permitir atributos personalizados
  return (
    <div {...{ vw: 'true' } as any} className="enabled">
      <div {...{ 'vw-access-button': 'true' } as any} className="active"></div>
      <div {...{ 'vw-plugin-wrapper': 'true' } as any}>
        <div className="vw-plugin-top-wrapper"></div>
      </div>
    </div>
  )
}
